<script setup>import{computed,onMounted,provide}from'vue';import{useRoute}from'vue-router';import{usePlanAdmin}from'../../../composables/usePlanAdmin';import FormErrors from '../../../components/ui/FormErrors.vue';import PlanStatusBadge from '../../../components/admin/plans/PlanStatusBadge.vue';const route=useRoute(),s=usePlanAdmin();provide('planAdmin',s);onMounted(()=>s.load(route.params.id));const tabs=[['admin.plans.show','Overview'],['admin.plans.limits','Limits'],['admin.plans.features','Features'],['admin.plans.subscriptions','Subscriptions'],['admin.plans.activity','Activity']];const money=computed(()=>s.plan.value?new Intl.NumberFormat(undefined,{style:'currency',currency:s.plan.value.currency,maximumFractionDigits:2}).format(Number(s.plan.value.price)):null);const limit=v=>v===null?'Unlimited':Number(v).toLocaleString()</script>
<template><div><p v-if="s.loading.value" class="loading-state">Loading plan...</p><FormErrors v-else-if="s.error.value" :error="s.error.value"/><template v-else-if="s.plan.value"><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.plans'}">Back to Subscription Plans</RouterLink><div class="mt-3 flex flex-wrap items-center gap-3"><h1>{{s.plan.value.name}}</h1><PlanStatusBadge :status="s.plan.value.status"/></div><p class="text-lg font-semibold text-slate-700">{{money}}<span v-if="Number(s.plan.value.price)"> / {{s.plan.value.billing_period}}</span></p></div><RouterLink class="btn" :to="{name:'admin.plans.edit',params:{id:route.params.id}}">Edit Plan</RouterLink></header><p v-if="route.query.created||route.query.updated" role="status" class="mb-5 rounded-xl bg-emerald-50 p-4 text-emerald-800">{{route.query.created?'Subscription plan created successfully.':'Subscription plan updated successfully.'}}</p><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><article class="summary-card"><p>Active Subscriptions</p><strong>{{s.plan.value.active_subscriptions_count}}</strong></article><article class="summary-card"><p>Trial Subscriptions</p><strong>{{s.plan.value.trial_subscriptions_count}}</strong></article><article class="summary-card"><p>Branch Limit</p><strong>{{limit(s.plan.value.branch_limit)}}</strong></article><article class="summary-card"><p>Member Limit</p><strong>{{limit(s.plan.value.member_limit)}}</strong></article><article class="summary-card"><p>Patient Limit</p><strong>{{limit(s.plan.value.patient_limit)}}</strong></article></div><nav class="clinic-tabs mt-6" aria-label="Plan management"><RouterLink v-for="[name,label] in tabs" :key="name" :to="{name,params:{id:route.params.id}}">{{label}}</RouterLink></nav><RouterView/></template></div></template>
